/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> grooveFunk16Lesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "Funk puts the groove in the sixteenths: an accented hat, a snare backbeat that never moves, and a kick that dances around the beat. Ghost notes between the backbeats make it feel alive rather than mechanical.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Hi-hat sixteenths alternating, accent on every quarter. Snare backbeat on 2 and 4 loud, ghost notes barely touching the head. The kick plays 1, the \"a\" of 1, the \"and\" of 2, 3 and the \"a\" of 3 — syncopated, but every note still lines up with a hat stroke.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Play the kick pattern alone against the hat first, then add the backbeat, then the ghosts. Ghosts must be quiet: if they sound like backbeats, the groove collapses. In lines 2, 7 and 8 some ghosts fall on a left-hand hat note, so the right hand plays the sixteenths on the hat alone there and the left hand stays on the snare. Line 4 opens the hat on the \"a\" of 2 and 4, line 6 moves the second backbeat to the \"and\" of 4.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "James Brown \"Cold Sweat\" and \"Funky Drummer\" with Clyde Stubblefield, Tower of Power with David Garibaldi, the Meters with Zigaboo Modeliste, and Red Hot Chili Peppers with Chad Smith.",
  ),
];
